code.source:
#include <iostream>
using namespace std;

int main() {
    int marks[5] = {72, 85, 64, 90, 58};
    int best = marks[0];
    for (int m : marks) {
        if (m > best) {
            best = m;
        }
    }
    cout << "Best: " << best << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int marks[5] = {72, 85, 64, 90, 58};
    for (int i = 4; i >= 0; i--) {
        cout << marks[i] << " ";
    }
    cout << endl;
    return 0;
}

